using System.ComponentModel;
using System.Text.Json;
using ModelContextProtocol.Server;

namespace ApiMcpServer;

/// <summary>
/// MCP tools that wrap a REST API via HttpClient.
/// Non-static class — HttpClient and ILogger are constructor-injected by the DI container.
/// </summary>
[McpServerToolType]
public class ApiTools(HttpClient httpClient, ILogger<ApiTools> logger)
{
    private static readonly JsonSerializerOptions JsonOptions = new() { WriteIndented = true };

    [McpServerTool, Description("List all items from the API.")]
    public async Task<string> ListItems(
        [Description("Maximum number of items to return (default 10)")] int limit = 10,
        CancellationToken cancellationToken = default)
    {
        logger.LogInformation("Listing items with limit {Limit}", limit);
        var response = await httpClient.GetAsync($"/api/items?limit={limit}", cancellationToken);
        response.EnsureSuccessStatusCode();
        var json = await response.Content.ReadAsStringAsync(cancellationToken);
        return json;
    }

    [McpServerTool, Description("Get a single item by its unique identifier.")]
    public async Task<string> GetItem(
        [Description("The unique identifier of the item")] string id,
        CancellationToken cancellationToken = default)
    {
        logger.LogInformation("Fetching item {Id}", id);
        var response = await httpClient.GetAsync($"/api/items/{id}", cancellationToken);
        response.EnsureSuccessStatusCode();
        return await response.Content.ReadAsStringAsync(cancellationToken);
    }

    [McpServerTool, Description("Create a new item with the given name and description.")]
    public async Task<string> CreateItem(
        [Description("Name of the item to create")] string name,
        [Description("Optional description for the item")] string? description = null,
        CancellationToken cancellationToken = default)
    {
        logger.LogInformation("Creating item {Name}", name);
        var payload = JsonSerializer.Serialize(new { name, description }, JsonOptions);
        var content = new StringContent(payload, System.Text.Encoding.UTF8, "application/json");
        var response = await httpClient.PostAsync("/api/items", content, cancellationToken);
        response.EnsureSuccessStatusCode();
        return await response.Content.ReadAsStringAsync(cancellationToken);
    }
}

